-- generated by permdock rls generate
-- fail-closed: never target a bypass role

-- permdock helpers (jwt: reads the role and memberships claims)
-- policies call them uncorrelated, so Postgres evaluates each once per statement

create schema if not exists "permdock";
revoke all on schema "permdock" from public;
grant usage on schema "permdock" to authenticated;

create table if not exists "permdock".role_permissions (
  role text not null,
  permission text not null,
  grant_key text not null,
  scope text not null check (scope ~ '^[a-z][a-z0-9_]*$'),
  effect text not null default 'allow' check (effect in ('allow', 'deny')),
  primary key (role, grant_key, scope)
);
alter table "permdock".role_permissions enable row level security;
revoke all on table "permdock".role_permissions from anonymous, authenticated, public;

insert into "permdock".role_permissions (role, permission, grant_key, scope, effect) values
  ('reader', 'note.read', 'note.read', 'global', 'allow')
on conflict (role, grant_key, scope) do update
  set permission = excluded.permission, effect = excluded.effect;
delete from "permdock".role_permissions
where (role, grant_key, scope) not in (values
  ('reader', 'note.read', 'global')
);

create or replace function "permdock".permdock_has(p_grant text)
returns boolean
language sql
stable
security definer
cost 1000
parallel safe
set search_path = ''
as $$
  select coalesce((select auth.user_id())::text, '') <> '' and exists (
    select 1
    from jsonb_array_elements_text(
      case jsonb_typeof(((select auth.session()) -> 'user_role'))
        when 'array' then ((select auth.session()) -> 'user_role')
        when 'string' then jsonb_build_array(((select auth.session()) -> 'user_role'))
        else '[]'::jsonb
      end
    ) r(role)
    join "permdock".role_permissions rp on rp.role = r.role
    where rp.grant_key = p_grant
      and rp.scope = 'global'
  )
$$;
revoke execute on function "permdock".permdock_has(text) from public, anonymous;
grant execute on function "permdock".permdock_has(text) to authenticated;

create or replace function "permdock".permitted_tenant_ids(p_grant text)
returns setof uuid
language sql
stable
security definer
cost 1000
rows 10
parallel safe
set search_path = ''
as $$
  select (m ->> 'id')::uuid
  from jsonb_array_elements(
      case jsonb_typeof(((select auth.session()) -> 'memberships')) when 'array' then ((select auth.session()) -> 'memberships') else '[]'::jsonb end
    ) m
    cross join lateral jsonb_array_elements_text(
      case jsonb_typeof(m -> 'roles') when 'array' then m -> 'roles' else '[]'::jsonb end
    ) r(role)
  join "permdock".role_permissions rp on rp.role = r.role
  where coalesce((select auth.user_id())::text, '') <> ''
    and rp.grant_key = p_grant
    and rp.scope = 'tenant'
    and m ->> 'scope' = 'tenant'
    and m ->> 'id' is not null
    and (nullif(((select auth.session()) ->> 'tenant_id'), '') is null or m ->> 'id' = nullif(((select auth.session()) ->> 'tenant_id'), ''))
    and case jsonb_typeof(m -> 'expires_at')
      when 'number' then (m ->> 'expires_at')::numeric > extract(epoch from now())
      else true
    end
$$;
revoke execute on function "permdock".permitted_tenant_ids(text) from public, anonymous;
grant execute on function "permdock".permitted_tenant_ids(text) to authenticated;

create or replace function "permdock".member_tenant_ids()
returns setof uuid
language sql
stable
security definer
cost 1000
set search_path = ''
as $$
  select distinct (m ->> 'id')::uuid
  from jsonb_array_elements(
    case jsonb_typeof(((select auth.session()) -> 'memberships')) when 'array' then ((select auth.session()) -> 'memberships') else '[]'::jsonb end
  ) m
  where coalesce((select auth.user_id())::text, '') <> ''
    and m ->> 'scope' = 'tenant'
    and m ->> 'id' is not null
    and jsonb_typeof(m -> 'roles') = 'array'
    and jsonb_array_length(m -> 'roles') > 0
    and case jsonb_typeof(m -> 'expires_at')
      when 'number' then (m ->> 'expires_at')::numeric > extract(epoch from now())
      else true
    end
$$;
revoke execute on function "permdock".member_tenant_ids() from public, anonymous;
grant execute on function "permdock".member_tenant_ids() to authenticated;

