cost 1000
parallel safe
set search_path = ''
set jit = off
as $$
  with pdk_m(key, scope, effect, grant_key) as (
    values
      ('note.read', 'global', 'allow', 'note.read')
  ),
  pdk_w as (
    select pdk_m.key, pdk_m.scope, pdk_m.effect, pdk_m.grant_key
    from pdk_m
    where pdk_m.key in (select k.key from pg_catalog.unnest(p_keys) k(key))
  ),
  pdk_g as (
  select rp.grant_key
  from jsonb_array_elements_text(
      case jsonb_typeof(((select auth.session()) -> 'user_role'))
        when 'array' then ((select auth.session()) -> 'user_role')
        when 'string' then jsonb_build_array(((select auth.session()) -> 'user_role'))
        else '[]'::jsonb
      end
    ) r(role)
  join "permdock".role_permissions rp on rp.role = r.role
  where coalesce((select auth.user_id())::text, '') <> ''
    and rp.scope = 'global'
  ),
  pdk_s as (
    select pdk_i.grant_key
    from (
  select (m ->> 'id')::uuid, rp.grant_key
  from jsonb_array_elements(
      case jsonb_typeof(((select auth.session()) -> 'memberships')) when 'array' then ((select auth.session()) -> 'memberships') else '[]'::jsonb end
    ) m
    cross join lateral jsonb_array_elements_text(
      case jsonb_typeof(m -> 'roles') when 'array' then m -> 'roles' else '[]'::jsonb end
    ) r(role)
  join "permdock".role_permissions rp on rp.role = r.role
  where coalesce((select auth.user_id())::text, '') <> ''
    and rp.scope = 'team'
    and m ->> 'scope' = 'team'
    and m ->> 'id' is not null
    and (nullif(((select auth.session()) ->> 'tenant_id'), '') is null or m -> 'within' ->> 'tenant' = nullif(((select auth.session()) ->> 'tenant_id'), ''))
    and case jsonb_typeof(m -> 'expires_at')
      when 'number' then (m ->> 'expires_at')::numeric > extract(epoch from now())
      else true
    end
    ) pdk_i(id, grant_key)
    where pdk_i.id = p_id
  ),
  pdk_h as (
    select pdk_w.key, pdk_w.scope, pdk_w.effect
    from pdk_w
    where (pdk_w.scope = 'global' and pdk_w.grant_key in (select pdk_g.grant_key from pdk_g))
      or (pdk_w.scope = 'team' and pdk_w.grant_key in (select pdk_s.grant_key from pdk_s))
  )
  select pdk_k.key
  from (select distinct pdk_w.key from pdk_w where pdk_w.effect = 'allow') pdk_k
  where (exists (select 1 from pdk_h where pdk_h.key = pdk_k.key and pdk_h.scope = 'global' and pdk_h.effect = 'allow') and not exists (select 1 from pdk_h where pdk_h.key = pdk_k.key and pdk_h.scope = 'global' and pdk_h.effect = 'deny'))
    or (exists (select 1 from pdk_h where pdk_h.key = pdk_k.key and pdk_h.scope = 'team' and pdk_h.effect = 'allow') and not exists (select 1 from pdk_h where pdk_h.key = pdk_k.key and pdk_h.scope = 'team' and pdk_h.effect = 'deny'))
  order by 1
$$;
revoke execute on function "permdock".permitted_team_permission_keys(uuid, text[]) from public, anonymous;
grant execute on function "permdock".permitted_team_permission_keys(uuid, text[]) to authenticated;

-- with p_conditioned true, also the instances a conditioned allow reaches, minus only unconditional denies: the caller applies the row condition
create or replace function "permdock".permitted_team_ids_by_permission(p_permission text, p_conditioned boolean)
returns setof uuid
language sql
stable
security definer
cost 1000
parallel safe
set search_path = ''
as $$
  select a.id
  from (
    select g.grant_key from "permdock".grant_keys(p_permission, 'team') g(grant_key)
    union all
    select g.grant_key from "permdock".grant_keys(p_permission, 'team', 'conditioned-allow') g(grant_key)
    where p_conditioned
  ) g
  cross join lateral "permdock".permitted_team_ids(g.grant_key) a(id)
  except
  select d.id
  from (
    select g.grant_key from "permdock".grant_keys(p_permission, 'team', 'deny') g(grant_key)
    except
    select g.grant_key from "permdock".grant_keys(p_permission, 'team', 'conditioned-deny') g(grant_key)
    where p_conditioned
  ) g
  cross join lateral "permdock".permitted_team_ids(g.grant_key) d(id)
$$;
revoke execute on function "permdock".permitted_team_ids_by_permission(text, boolean) from public, anonymous;
grant execute on function "permdock".permitted_team_ids_by_permission(text, boolean) to authenticated;

alter table "public"."note" enable row level security;
revoke all on table "public"."note" from anonymous, authenticated;
grant select on table "public"."note" to authenticated;

drop policy if exists "note_select" on "public"."note";
create policy "note_select"
  on "public"."note"
  as permissive
  for select
  to authenticated
  using ((select "permdock".permdock_has('note.read')));
